import {takeSourceTypes,recordableTakeActor} from './take-sources.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function takeSourcesMarkup(sources,objects=[],disabled=false){const lock=disabled?'disabled':'',rows=sources??[],actors=objects.filter(recordableTakeActor);return '<fieldset class="take-source-list"><legend>녹화 소스</legend><label>대상 방식<select data-take-source-mode '+lock+'><option value="selection" '+(sources===undefined?'selected':'')+'>현재 선택 · 없으면 전체</option><option value="sources" '+(sources!==undefined?'selected':'')+'>저장된 소스 목록</option></select></label>'+(sources===undefined?'':'<div>'+rows.map((s,i)=>'<div class="take-source-row"><input type="checkbox" aria-label="소스 '+(i+1)+' 활성" data-take-source-index="'+i+'" data-take-source-field="enabled" '+(s.enabled?'checked':'')+' '+lock+'><span>'+esc(takeSourceTypes.find(([k])=>k===s.type)?.[1])+'</span>'+(s.type==='actor'?'<select aria-label="소스 '+(i+1)+' 액터" data-take-source-index="'+i+'" data-take-source-field="actor" '+lock+'>'+(!actors.some(o=>o.id===s.actor)?'<option value="'+esc(s.actor)+'">연결 없음 · '+esc(s.actor)+'</option>':'')+actors.map(o=>'<option value="'+esc(o.id)+'" '+(s.actor===o.id?'selected':'')+'>'+esc(o.name||o.id)+'</option>').join('')+'</select>':'<span>'+(s.type==='player'?'현재 조종 폰':'시작 시 활성 액터')+'</span>')+'<button type="button" data-take-source-remove="'+i+'" aria-label="소스 '+(i+1)+' 삭제" '+lock+'>×</button></div>').join('')+'</div><div class="take-source-actions"><select data-take-source-type aria-label="추가할 녹화 소스" '+lock+'>'+takeSourceTypes.map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select><button type="button" data-take-source-add '+lock+'>소스 추가</button><button type="button" data-take-source-selection '+lock+'>선택 추가</button></div>')+'</fieldset>';}
